KG42.register("rules-afd427e29b9dbf39d3031837",{"id":"28-multiclass_prosumer_preferences::v141-c-R004","paper":"28-multiclass_prosumer_preferences","record":{"rule_id":"v141-c-R004","mechanism_id":"v141-a-M01","name":"Local market coordinator","process_stage":"coordination","market_meaning":"Prosumers submit their net power demands for each energy class over the time horizon to the platform agent. Scope: Proposed distribution-network P2P market; distributed multiclass optimisation over the time horizon. Access to the wholesale electricity market is reserved to the P2P platform. Scope: The proposed P2P platform's interface with the wholesale electricity market. The P2P platform is assumed to operate as a price-taker in the wholesale electricity market. Scope: Assumed wholesale-market operation of the proposed P2P platform.","independence_rationale":"Relations governed by the approved function coordination.local_operator under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","coordination.local_operator"],"E":[{"edge_id":"v141-c-R004-E001","source":"bidding.demand","target":"coordination.local_operator","type":"links","constraint_ids":["v141-c-R004-C001"],"evidence_ids":["v141-b-g02-e023"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Assumed wholesale-market operation of the proposed P2P platform. | Proposed distribution-network P2P market; distributed multiclass optimisation over the time horizon. | The proposed P2P platform's interface with the wholesale electricity market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E05","v141-b-g01-E10","v141-b-g02-e023"]},"x":[{"variable_id":"v141-c-R004-x-grid-net-demand","symbol":"\\tilde{x}_{ig}^{(t)}(\\kappa)","meaning":"Average net power demand for grid-class energy calculated by prosumer i and reported to the platform agent at interval t in iteration kappa.","kind":"operational","domain":"real-valued average net power demand; the source does not separately state a sign restriction for this reported quantity","unit":null,"indices":["i∈N","t∈T","κ"],"evidence_ids":["v141-b-g02-e023"]},{"variable_id":"v141-c-R004-x-class-net-demand","symbol":"\\tilde{x}_{ik}^{(t)}(\\kappa)","meaning":"Average net power demand for energy class k calculated by prosumer i and reported to the platform agent at interval t in iteration kappa.","kind":"operational","domain":"real-valued average net power demand; the source does not separately state a sign restriction for this reported quantity","unit":null,"indices":["i∈N","k∈K","t∈T","κ"],"evidence_ids":["v141-b-g02-e023"]},{"variable_id":"v141-c-R004-z-grid-load","symbol":"z_{ig}^{(t)}(\\kappa)","meaning":"Average allocated load power of prosumer i supplied by grid-class energy at interval t in iteration kappa.","kind":"operational","domain":"nonnegative real-valued average allocated load power (source eq. (8) imposes nonnegativity for grid-class load allocation)","unit":null,"indices":["i∈N","t∈T","κ"],"evidence_ids":["v141-b-g02-e023","v141-b-G01-E20"]},{"variable_id":"v141-c-R004-z-class-load","symbol":"z_{ik}^{(t)}(\\kappa)","meaning":"Average allocated load power of prosumer i supplied by energy class k at interval t in iteration kappa.","kind":"operational","domain":"nonnegative real-valued average allocated load power (source eq. (8) imposes nonnegativity for class load allocation)","unit":null,"indices":["i∈N","k∈K","t∈T","κ"],"evidence_ids":["v141-b-g02-e023","v141-b-G01-E20"]},{"variable_id":"v141-c-R004-y-grid-renewable","symbol":"y_{ig}^{(t)}(\\kappa)","meaning":"Average renewable source output power of prosumer i allocated to grid-class energy at interval t in iteration kappa.","kind":"operational","domain":"nonnegative real-valued average renewable output power (source eq. (10) imposes nonnegativity)","unit":null,"indices":["i∈N","t∈T","κ"],"evidence_ids":["v141-b-g02-e023","v141-b-G01-E21"]},{"variable_id":"v141-c-R004-y-class-renewable","symbol":"y_{ik}^{(t)}(\\kappa)","meaning":"Average renewable source output power of prosumer i allocated to energy class k at interval t in iteration kappa.","kind":"operational","domain":"nonnegative real-valued average renewable output power (source eq. (10) imposes nonnegativity)","unit":null,"indices":["i∈N","k∈K","t∈T","κ"],"evidence_ids":["v141-b-g02-e023","v141-b-G01-E21"]},{"variable_id":"v141-c-R004-b-grid-battery","symbol":"b_{ig}^{(t)}(\\kappa)","meaning":"Average battery output power of prosumer i allocated to grid-class energy at interval t in iteration kappa.","kind":"operational","domain":"real-valued average battery output power; the source limits aggregate battery output via eq. (17) rather than separately stating a per-class sign restriction","unit":null,"indices":["i∈N","t∈T","κ"],"evidence_ids":["v141-b-g02-e023","v141-b-G01-E26"]},{"variable_id":"v141-c-R004-b-class-battery","symbol":"b_{ik}^{(t)}(\\kappa)","meaning":"Average battery output power of prosumer i allocated to energy class k at interval t in iteration kappa.","kind":"operational","domain":"real-valued average battery output power; the source limits aggregate battery output via eq. (17) rather than separately stating a per-class sign restriction","unit":null,"indices":["i∈N","k∈K","t∈T","κ"],"evidence_ids":["v141-b-g02-e023","v141-b-G01-E26"]}],"theta":[],"phi":[{"constraint_id":"v141-c-R004-C001","kind":"mathematical","role":"core","statement":"Prosumers submit their net power demands for each energy class over the time horizon to the platform agent. Scope: Proposed distribution-network P2P market; distributed multiclass optimisation over the time horizon.","expression":"\\tilde{x}_{ig}^{(t)}(\\kappa)=z_{ig}^{(t)}(\\kappa)-y_{ig}^{(t)}(\\kappa)-b_{ig}^{(t)}(\\kappa),\\quad t\\in\\mathcal{T};\\qquad \\tilde{x}_{ik}^{(t)}(\\kappa)=z_{ik}^{(t)}(\\kappa)-y_{ik}^{(t)}(\\kappa)-b_{ik}^{(t)}(\\kappa),\\quad k\\in\\mathcal{K},\\ t\\in\\mathcal{T}.","formalization_origin":"source","template_id":null,"members":["bidding.demand","coordination.local_operator"],"variable_refs":["v141-c-R004-x-grid-net-demand","v141-c-R004-x-class-net-demand","v141-c-R004-z-grid-load","v141-c-R004-z-class-load","v141-c-R004-y-grid-renewable","v141-c-R004-y-class-renewable","v141-c-R004-b-grid-battery","v141-c-R004-b-class-battery"],"parameter_refs":[],"evidence_ids":["v141-b-g02-e023"]},{"constraint_id":"v141-c-R004-C002","kind":"procedural","role":"core","statement":"Access to the wholesale electricity market is reserved to the P2P platform. Scope: The proposed P2P platform's interface with the wholesale electricity market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E05"]},{"constraint_id":"v141-c-R004-C003","kind":"procedural","role":"core","statement":"The P2P platform is assumed to operate as a price-taker in the wholesale electricity market. Scope: Assumed wholesale-market operation of the proposed P2P platform.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E10","v141-b-g03-e06"]}],"pi":[{"evidence_id":"v141-b-g01-E05","location":{"location_id":"src-96285c344a-p02-c2r2__v141-a-M01-participation","page":2,"printed_page":null,"section":"II. Principle of Operation","anchor_text":"sed co- Fig. 1. A distribution network with three prosumers and three energy classes. The green pros","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"3) Satisfy informational constraints for scalability and data privacy: Only the P2P platform has access to the wholesale electricity market and each prosumers’ energy resource capacities, preferences and renewable generation and load predictions are private information."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-96285c344a-p03-c1r3__v141-a-M01-pricing","page":3,"printed_page":null,"section":"II. Principle of Operation","anchor_text":"the current trading interval, the trading interval recedes by a t0 step and the prosumers update the","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"It is assumed that the P2P energy market platform operates as a price-taker in the wholesale electricity market. The platform agent is programmed to set prices that maximise social welfare, and the individual prosumers are programmed to operate as competitive price-takers. This is desirable for all participants if the platform owner faces competition from other potential platforms, so it cannot set prices to maximise profits, and there are sufficient prosumers so that they cannot improve their position through strategic price-setting behaviour [33]. If these conditions are not met over the long term, the platform owner/prosumers with market power may need to be compensated to incentivise their participation."},{"evidence_id":"v141-b-g02-e023","location":{"location_id":"src-96285c344a-p06-c1r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":"IV. Distributed Price-Directed Optimisation","anchor_text":"k∈K ρ 2 + z(t)ik (κ)−x(t)ik (κ−1)−y(t)ik (κ)−b(t)ik (κ) . 2 ρ > 0 in the penalty terms is the ADMM s","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"2) The prosumers calculate their net power demands for each energy class over the time horizon, and send this information to the platform agent, \\[ \\tilde{x}_{ig}^{(t)}(\\kappa)=z_{ig}^{(t)}(\\kappa)-y_{ig}^{(t)}(\\kappa)-b_{ig}^{(t)}(\\kappa),\\quad t\\in\\mathcal T, \\] \\[ \\tilde{x}_{ik}^{(t)}(\\kappa)=z_{ik}^{(t)}(\\kappa)-y_{ik}^{(t)}(\\kappa)-b_{ik}^{(t)}(\\kappa),\\quad k\\in\\mathcal K,\\ t\\in\\mathcal T. \\]"},{"evidence_id":"v141-b-G01-E20","location":{"location_id":"src-96285c344a-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 5, SEPTEMBER 2019 reserved for low-income household","equation_id":"(7)-(8)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Also, each prosumer, i \\in \\mathcal{N}, has load constraints, renewable generation constraints and battery constraints. The prosumer load constraints require that the total power allocated to its load meets its load predictions, z_i^{pred(t)}, \\forall t \\in \\mathcal{T}. Let \\mathcal{K}_i \\subseteq \\mathcal{K} be the set of energy classes that prosumer i is allowed to use to supply its loads (e.g., in the example from Fig. 1, subsidised energy is reserved for low-income households). \\sum_{k \\in \\mathcal{K}_i} z_{ik}^{(t)} + z_{ig}^{(t)} = z_i^{pred(t)}, \\forall t \\in \\mathcal{T}. \\quad 0 \\le z_{ig}^{(t)}, 0 \\le z_{ik}^{(t)}, \\forall k \\in \\mathcal{K}, \\forall t \\in \\mathcal{T}."},{"evidence_id":"v141-b-G01-E21","location":{"location_id":"src-96285c344a-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 5, SEPTEMBER 2019 reserved for low-income household","equation_id":"(9)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"For prosumer i \\in \\mathcal{N}, let y_i^{pred(t)} be the predicted generation capacity at interval t. \\sum_{k \\in \\mathcal{K}} y_{ik}^{(t)} + y_{ig}^{(t)} = y_i^{pred(t)}, \\forall t \\in \\mathcal{T}. \\quad 0 \\le y_{ig}^{(t)}, 0 \\le y_{ik}^{(t)}, \\forall k \\in \\mathcal{K}, \\forall t \\in \\mathcal{T}."},{"evidence_id":"v141-b-G01-E26","location":{"location_id":"src-96285c344a-p05-c1r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"MORSTYN AND MCCULLOCH: MULTICLASS ENERGY MANAGEMENT FOR PEER-TO-P energy classes that can be substit","equation_id":"(17)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The battery also has output power limits. Let B_{ci}^{max} be the maximum charging power and B_{di}^{max} be the maximum discharging power. The battery output power constraints for prosumer i are given by, -B_{ci}^{max} \\le \\sum_{k \\in \\mathcal{K}} b_{ik}^{(t)} + b_{ig}^{(t)} \\le B_{di}^{max}, \\forall t \\in \\mathcal{T}."},{"evidence_id":"v141-b-g03-e06","location":{"location_id":"src-96285c344a-p08-c2r3__v141-a-M01-activation","page":8,"printed_page":null,"section":"VI. Conclusion","anchor_text":"product, based on attributes of its source that are perceived by prosumers to have value. This has b","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"restatement"},"source_text":"First, it has been assumed that the P2P energy market platform is a relatively small participant in the wholesale market, and does not have a significant effect on wholesale energy prices."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":"No fixed scalar parameter is stated in the net-demand reporting equation. The sets N, K and T and the iteration index kappa are recorded as indices in the variable definitions, not as theta objects."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"coordination.local_operator","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e023","quote":"The prosumers calculate their net power demands for each energy class over the time horizon, and send this information to the platform agent"}],[{"evidence_id":"v141-b-g01-E05","quote":"Only the P2P platform has access to the wholesale electricity market"}],[{"evidence_id":"v141-b-g01-E10","quote":"It is assumed that the P2P energy market platform operates as a price-taker in the wholesale electricity market."}]],"C2_formalization":{"graph_sha256":"210e1e47c5198bca6d4bc81d5c619b86f5a9974d6c4e1989a00b2291a32c0bee","applicability":"formalized","reason":"C001 is formalized from the supplied net-demand reporting equation: prosumers compute net grid-class and class-k demands from allocated load, renewable output and battery output, then send them to the platform agent. C002 and C003 remain procedural wholesale-access and price-taking assumptions because the supplied sources state them in words rather than as quantitative relations in this rule. This formalization uses unreviewed B evidence and does not assert independent source review.","bindings":[{"object_id":"v141-c-R004-C001","node_ids":["bidding.demand","coordination.local_operator"],"edge_ids":["v141-c-R004-E001"],"rationale":"The source equation defines the net grid-class and class-k demands reported by prosumers to the platform agent, and E001 links the demand submission node bidding.demand to the coordinator node coordination.local_operator."},{"object_id":"v141-c-R004-C002","node_ids":["coordination.local_operator"],"edge_ids":[],"rationale":"The wholesale-access restriction is an institutional constraint on the platform agent's exclusive interface with the wholesale market; no separate quantitative variable or edge is stated in this rule."},{"object_id":"v141-c-R004-C003","node_ids":["coordination.local_operator"],"edge_ids":[],"rationale":"The price-taking assumption conditions the platform agent's wholesale-market behavior; the supplied evidence states it verbally rather than as an algebraic relation in this rule."},{"object_id":"v141-c-R004-x-grid-net-demand","node_ids":["bidding.demand","coordination.local_operator"],"edge_ids":["v141-c-R004-E001"],"rationale":"This is the reported grid-class net demand crossing the demand-submission link from prosumers to the platform agent."},{"object_id":"v141-c-R004-x-class-net-demand","node_ids":["bidding.demand","coordination.local_operator"],"edge_ids":["v141-c-R004-E001"],"rationale":"This is the reported class-k net demand crossing the demand-submission link from prosumers to the platform agent."},{"object_id":"v141-c-R004-z-grid-load","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"Allocated grid-class load is a local prosumer quantity used to compute the net demand that is submitted; the submitted quantity, not this local term itself, crosses E001."},{"object_id":"v141-c-R004-z-class-load","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"Allocated class-k load is a local prosumer quantity used to compute the net demand that is submitted; the submitted quantity, not this local term itself, crosses E001."},{"object_id":"v141-c-R004-y-grid-renewable","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"Grid-class renewable output is a local prosumer quantity used to compute the net demand that is submitted to the coordinator."},{"object_id":"v141-c-R004-y-class-renewable","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"Class-k renewable output is a local prosumer quantity used to compute the net demand that is submitted to the coordinator."},{"object_id":"v141-c-R004-b-grid-battery","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"Grid-class battery output is a local prosumer quantity used to compute the net demand that is submitted to the coordinator."},{"object_id":"v141-c-R004-b-class-battery","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"Class-k battery output is a local prosumer quantity used to compute the net demand that is submitted to the coordinator."}],"revision_requests":[]}},"quarantined_references":[]}});
